//! The Epoch of a TimeFrame with only its TimeOrigin set, checked against
//! the C library.
//!
//! `time_epoch_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/time_epoch_probe.c`. C's `GetEpoch`
//! (timeframe.c:2480) converts the TimeOrigin to a TDB MJD. For UT1, GMST,
//! LAST and LMST it maps the origin to UT1 first, but then converts the raw
//! TimeOrigin, not that UT1 value, with the Mapping from UTC MJD in days to
//! TDB (timeframe.c:2556), so the result is that of a UTC MJD whatever the
//! System.

#[path = "time_epoch_oracle/cases.rs"]
mod cases;

use ast_core::frames::{TimeFrame, TimeScale, TimeSystem};

fn frame(system: &str, scale: &str, origin: f64, extra: &str) -> TimeFrame {
    let mut f = TimeFrame::new(TimeSystem::Mjd);
    f.set_system(TimeSystem::parse(system).unwrap()).unwrap();
    f.set_timescale(TimeScale::parse(scale).unwrap()).unwrap();
    f.set_time_origin_cur(origin).unwrap();
    for setting in extra.split(',').filter(|s| !s.is_empty()) {
        match setting.split_once('=').unwrap() {
            ("Dut1", v) => f.set_dut1(v.parse().unwrap()),
            ("ObsLon", v) => f.set_obs_lon(v.parse::<f64>().unwrap().to_radians()),
            other => panic!("no Rust set-up for {other:?}"),
        }
    }
    f
}

#[test]
fn epoch_from_time_origin_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(system, scale, origin, extra, want) in cases::CASES {
        let f = frame(system, scale, origin, extra);
        assert!(!f.test_epoch());
        let got = Some(f.epoch_mjd());
        if got != want {
            failures.push(format!(
                "{system} {scale} [{extra}]: got {got:?}, C gives {want:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}
